from dataclasses import dataclass, field
from typing import Optional

HEADING = re.compile(
    r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$"
)
COMMENT = re.compile(r"<!--.*?-->", re.DOTALL)
_MARK = "\x00"


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    """Remove HTML comments, dropping trailing whitespace they leave behind."""
    text = COMMENT.sub(_MARK, text)
    lines = []
    for line in text.split("\n"):
        if _MARK in line:
            line = line.replace(_MARK, "").rstrip()
        lines.append(line)
    return "\n".join(lines)


def parse_changelog(text):
    releases = []
    current = None
    for line in strip_comments(text).splitlines():
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                current = None
                continue
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def _collapse_blank_lines(lines):
    out = []
    for line in lines:
        if not line.strip():
            if out and out[-1] == "":
                continue
            line = ""
        out.append(line)
    while out and out[0] == "":
        out.pop(0)
    while out and out[-1] == "":
        out.pop()
    return out


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            body = "\n".join(_collapse_blank_lines(release.body))
            title = f"# {release.version} ({release.date})" if release.date else f"# {release.version}"
            return f"{title}\n\n{body}\n"
    raise LookupError(version)

